import "./Login.css";
import login_main_img from "./login_main_img.gif";
import naver_logo_btn from "./naver_logo_btn.png";
import React from "react";
import Button from "@mui/material/Button";

function Login() {
  const response_type = "code";
  const clientId = "eV5oSQK9GyDD58KC4_Xl";
  const redirectUri =
    "https://maeun.github.io/hiyoumore/#/oauth/naver/callback";
  const state = Math.random().toString(36).substring(2);

  localStorage.setItem("naverState", state);

  return (
    <div className="login-container">
      <img src={login_main_img} alt="login main" />

      <Button
        variant="outlined"
        href={`https://nid.naver.com/oauth2.0/authorize?response_type=${response_type}&client_id=${clientId}&redirect_uri=${redirectUri}&state=${state}`}
        sx={{
          height: "45px",
          width: "100%",
          color: "#03C75A",
          borderColor: "#03C75A",
          borderWidth: "2px",
          backgroundColor: "#FFFFFF",
          "&:hover": {
            borderColor: "#03C75A",
            borderWidth: "2px",
            backgroundColor: "rgba(3, 199, 90, 0.04)",
          },
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          margin: "0 auto",
        }}
      >
        <img
          src={naver_logo_btn}
          alt="naver login"
          style={{
            height: "90%",
            marginRight: 8,
          }}
        />
        네이버로 로그인하기
      </Button>
    </div>
  );
}

export default Login;
