import "./Mypage.css";
import something_going_wrong from "./something_going_wrong.png";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { TextField, Avatar, Box, Typography, Button } from "@mui/material";
import { useContext, useEffect, useState } from "react";
import AuthContext from "./AuthContext";
import { toast, ToastContainer, Bounce } from "react-toastify";

function Mypage() {
  const { isLoggedIn, setIsLoggedIn, token } = useContext(AuthContext);
  const [userInfo, setUserInfo] = useState(null);
  const navigate = useNavigate();

  const profileImages = [
    process.env.PUBLIC_URL + "/profile_yellow.png",
    process.env.PUBLIC_URL + "/profile_blue.png",
    process.env.PUBLIC_URL + "/profile_black.png", // 새로운 이미지 추가
    process.env.PUBLIC_URL + "/profile_orange.png", // 새로운 이미지 추가
  ];

  const defaultProfileImage =
    profileImages[Math.floor(Math.random() * profileImages.length)];

  useEffect(() => {
    if (isLoggedIn && token) {
      fetchUserInfo();
    }
  }, [isLoggedIn, token]);

  const fetchUserInfo = async () => {
    try {
      const response = await axios.get("https://kapi.kakao.com/v2/user/me", {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/x-www-form-urlencoded",
        },
      });

      setUserInfo(response.data);
    } catch (error) {
      console.error("Error fetching the user info:", error);
    }
  };

  const handleSignout = async () => {
    try {
      const response = await axios.post(
        "https://kapi.kakao.com/v1/user/unlink",
        {}, // 빈 객체를 데이터로 전달
        {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/x-www-form-urlencoded",
          },
        }
      );

      console.log("Signout success", response.data);

      // 로그인 상태 업데이트
      setIsLoggedIn(false);

      toast(<b>🤧 탈퇴되었습니다 🤧</b>, {
        position: "top-center",
        autoClose: 900,
        hideProgressBar: false,
        closeOnClick: true,
        pauseOnHover: true,
        draggable: true,
        progress: undefined,
        theme: "light",
        transition: Bounce,
      });
    } catch (error) {
      console.error("Signout failed:", error);
      toast.error("Signout failed. Please try again.");
    }
    navigate("/");
  };

  return (
    <div>
      <ToastContainer />
      {isLoggedIn ? (
        <div>
          {userInfo && (
            <div>
              <Box
                sx={{
                  width: "100%",
                  maxWidth: "400px", // 동일한 최대 너비
                  margin: "0 auto", // 가운데 정렬
                  padding: "16px",
                  backgroundColor: "#f9f9f9",
                  borderRadius: "8px",
                  boxShadow: "0 4px 8px rgba(0, 0, 0, 0.1)",
                }}
              >
                <Box
                  sx={{
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center",
                    width: "100%",
                  }}
                >
                  <Avatar
                    src={
                      userInfo.kakao_account.profile.profile_image_url ||
                      defaultProfileImage
                    }
                    alt=""
                    sx={{ width: 80, height: 80, marginBottom: "16px" }}
                  />
                  <Typography
                    variant="h6"
                    component="p"
                    sx={{ marginBottom: "8px" }}
                  >
                    {userInfo.kakao_account.profile.nickname}님 환영합니다
                  </Typography>
                  <Typography
                    variant="body1"
                    sx={{ marginBottom: "16px", color: "#555" }}
                  >
                    {userInfo.kakao_account.email}
                  </Typography>
                  <TextField
                    id="standard-read-only-input"
                    label="Solana Wallet Address"
                    defaultValue="Hello World"
                    InputProps={{
                      readOnly: true,
                    }}
                    variant="standard"
                    fullWidth
                  />
                </Box>
                <Button
                  component="section"
                  sx={{
                    width: "100%",
                    border: "2px dashed grey",
                    marginTop: "16px",
                    padding: "8px",
                    boxSizing: "border-box",
                  }}
                  onClick={handleSignout}
                >
                  🥺 탈퇴하기
                </Button>
              </Box>
            </div>
          )}
        </div>
      ) : (
        <div>
          <img src={something_going_wrong} alt="Something went wrong" />
        </div>
      )}
    </div>
  );
}

export default Mypage;
