import "./Header.css";
import { Link } from "react-router-dom";

function Header() {
  return (
    <div class="header">
      <Link to="/hiyoumore">
        <div class="header_text">
          <img
            src={process.env.PUBLIC_URL + "/logo192.png"}
            alt="logo"
            class="logo"
          />
          hiyoumore
        </div>
      </Link>
    </div>
  );
}

export default Header;
